package com.nigson.commerce.catalogue;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.time.Clock;
import org.springframework.jdbc.core.JdbcTemplate;
import tools.jackson.databind.JsonNode;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;

/** Commerce-owned, market-filtered recommendations and the AI public knowledge projection. */
public final class RecommendationService {
    private final JdbcTemplate jdbc; private final ProductRepository products; private final CatalogueAssets assets; private final io.micrometer.core.instrument.MeterRegistry metrics;
    private final CatalogueAuthority authority; private final PlatformStore commands; private final AuditWriter audit; private final Clock clock;
    public RecommendationService(JdbcTemplate jdbc,ProductRepository products,CatalogueAssets assets,CatalogueAuthority authority,PlatformStore commands,AuditWriter audit,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics){this.jdbc=jdbc;this.products=products;this.assets=assets;this.authority=authority;this.commands=commands;this.audit=audit;this.clock=clock;this.metrics=metrics;}
    private static final String ELIGIBLE="p.status='ACTIVE' AND p.deleted_at IS NULL AND EXISTS(SELECT 1 FROM commerce.product_market_eligibility e JOIN commerce.market m ON m.id=e.market_id WHERE e.product_id=p.id AND e.eligible AND m.enabled AND m.code=?)";
    public List<RecommendationValues.PublicItem> publicList(UUID product,String market,int limit){
        CatalogueReads.market(market);if(limit<1||limit>12)throw ApiValues.invalid();
        if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.market WHERE code=? AND enabled)",Boolean.class,market)))throw new Problem.Failure(ProblemCode.NOT_FOUND);
        if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.product p WHERE p.id=? AND "+ELIGIBLE+")",Boolean.class,product,market)))throw new Problem.Failure(ProblemCode.NOT_FOUND);
        var result=jdbc.query("SELECT p.id,p.name,r.kind FROM commerce.product_recommendation r JOIN commerce.product p ON p.id=r.related_product_id WHERE r.product_id=? AND r.active AND "+ELIGIBLE+" ORDER BY r.priority,r.kind,p.id LIMIT ?",(r,n)->new RecommendationValues.PublicItem(r.getObject(1,UUID.class),r.getString(2),r.getString(3)),product,market,limit);
        if(result.size()<limit){var popular=jdbc.query("SELECT p.id,p.name FROM commerce.sales_order o JOIN commerce.market m ON m.id=o.market_id JOIN commerce.order_line l ON l.order_id=o.id JOIN commerce.sku s ON s.id=l.sku_id JOIN commerce.product p ON p.id=s.product_id WHERE m.code=? AND m.enabled AND o.payment_status IN ('PAID','PARTIALLY_REFUNDED') AND o.status NOT IN ('CANCELLED','PAYMENT_HOLD') AND p.id<>? AND p.status='ACTIVE' AND p.deleted_at IS NULL AND EXISTS(SELECT 1 FROM commerce.product_market_eligibility e WHERE e.product_id=p.id AND e.market_id=m.id AND e.eligible) AND NOT EXISTS(SELECT 1 FROM commerce.product_recommendation r WHERE r.product_id=? AND r.related_product_id=p.id AND r.active) GROUP BY p.id,p.name ORDER BY sum(l.quantity) DESC,p.id LIMIT ?",(r,n)->new RecommendationValues.PublicItem(r.getObject(1,UUID.class),r.getString(2),"POPULAR"),market,product,product,limit-result.size());result=new ArrayList<>(result);result.addAll(popular);}
        metrics.counter("nigson.catalogue.reads","operation","RECOMMENDATIONS").increment();return List.copyOf(result);
    }
    public RecommendationValues.Result get(UUID product){
        var head=products.find(product,false);var items=jdbc.query("SELECT related_product_id,kind,priority FROM commerce.product_recommendation WHERE product_id=? AND active ORDER BY priority,kind,related_product_id LIMIT 101",(r,n)->new RecommendationValues.Recommendation(r.getObject(1,UUID.class),r.getString(2),r.getInt(3)),product);if(items.size()>100)throw new Problem.Failure(ProblemCode.CATALOGUE_RULE_VIOLATION);return new RecommendationValues.Result(product,items,head.version());
    }
    public RecommendationValues.Result replace(ActorAssertion.Actor actor,UUID product,long expected,JsonNode input,String key,UUID correlation){
        authority.require(actor,"SALES");ApiValues.idempotencyKey(key);if(expected<0||expected==Long.MAX_VALUE||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();var items=RecommendationValues.command(input);var canonical=EventCodec.JSON.valueToTree(Map.of("productId",product,"version",expected,"items",items));
        var response=commands.executeLocal(actor.party().toString(),"API-074",key,canonical,db->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");authority.stabilize(actor,"SALES");var before=products.find(product,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!before.status().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.CATALOGUE_RULE_VIOLATION);
            for(var item:items){if(item.relatedProductId().equals(product))throw ApiValues.invalid();var active=jdbc.query("SELECT id FROM commerce.product WHERE id=? AND status='ACTIVE' AND deleted_at IS NULL FOR SHARE",(r,n)->r.getObject(1,UUID.class),item.relatedProductId());if(active.isEmpty()||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.product_market_eligibility a JOIN commerce.market m ON m.id=a.market_id JOIN commerce.product_market_eligibility b ON b.market_id=m.id WHERE a.product_id=? AND a.eligible AND b.product_id=? AND b.eligible AND m.enabled)",Boolean.class,product,item.relatedProductId())))throw new Problem.Failure(ProblemCode.CATALOGUE_RULE_VIOLATION);}
            var existing=jdbc.query("SELECT id,related_product_id,kind,priority,active,version FROM commerce.product_recommendation WHERE product_id=? ORDER BY related_product_id,kind FOR UPDATE",(r,n)->new Existing(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getInt(4),r.getBoolean(5),r.getLong(6)),product);var desired=new HashMap<String,RecommendationValues.Command>();for(var i:items)desired.put(i.relatedProductId()+":"+i.kind(),i);boolean changed=false;var actorId=actor.party().toString();
            for(var old:existing){String k=old.related()+":"+old.kind();var next=desired.remove(k);boolean active=next!=null;int priority=active?next.priority():old.priority();if(old.active()!=active||old.priority()!=priority){jdbc.update("UPDATE commerce.product_recommendation SET active=?,priority=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",active,priority,java.sql.Timestamp.from(clock.instant()),actorId,old.id());changed=true;}}
            for(var next:desired.values()){jdbc.update("INSERT INTO commerce.product_recommendation(id,created_by,updated_by,product_id,related_product_id,kind,priority,active) VALUES (?,?,?,?,?,?,?,true)",EventCodec.uuid7(clock.instant()),actorId,actorId,product,next.relatedProductId(),next.kind(),next.priority());changed=true;}
            ProductRepository.Snapshot after=before;if(changed){products.touch(product,actorId);after=products.find(product,false);audit.append(actorId,AuditValues.ActorKind.USER,AuditValues.Action.PRODUCT_UPDATE,AuditValues.Resource.PRODUCT,product,correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("recommendations",existing.size()),Map.of("recommendations",items.size(),"version",after.version()),null);org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.catalogue.commands","operation","RECOMMENDATIONS").increment();}});}
            var result=new RecommendationValues.Result(product,items.stream().map(i->new RecommendationValues.Recommendation(i.relatedProductId(),i.kind(),i.priority())).toList(),after.version());return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(result),product);
        });return EventCodec.JSON.treeToValue(response.body(),RecommendationValues.Result.class);
    }
    public RecommendationValues.Knowledge knowledge(PrivateWorkload.Proof proof,UUID id){
        var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-123")&&r.owner().equals("commerce")&&r.client().equals("nigson-ai")&&r.scope().equals("knowledge.read")).findFirst().orElseThrow(ActorAssertion::denied);
        if(proof==null||!proof.client().equals("nigson-ai")||proof.route()==null||!proof.route().equals(route)||proof.actor()!=null)throw ActorAssertion.denied();
        var row=jdbc.query("SELECT p.id,p.revision,p.name,p.description,p.specifications::text FROM commerce.product p WHERE p.id=? AND p.status='ACTIVE' AND p.deleted_at IS NULL",(r,n)->new KnowledgeRow(r.getObject(1,UUID.class),r.getLong(2),r.getString(3),r.getString(4),EventCodec.JSON.readTree(r.getString(5))),id);if(row.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);
        var markets=products.eligibleMarkets(id);if(markets.isEmpty())throw new Problem.Failure(ProblemCode.NOT_FOUND);var image=assets.published(id).stream().filter(a->a.purpose().equals("IMAGE")).map(CatalogueValues.Asset::url).findFirst().orElseThrow(()->new Problem.Failure(ProblemCode.NOT_FOUND));var v=row.getFirst();String checksum=checksum(v,markets,image);metrics.counter("nigson.catalogue.reads","operation","AI_KNOWLEDGE").increment();return new RecommendationValues.Knowledge(id,v.revision(),true,markets,v.name(),v.description(),v.specifications(),image,checksum);
    }
    private String checksum(KnowledgeRow r,List<String> markets,String url){try{var content=new LinkedHashMap<String,Object>();content.put("id",r.id());content.put("revision",r.revision());content.put("approved",true);content.put("marketCodes",markets);content.put("name",r.name());content.put("description",r.description());content.put("specifications",r.specifications());content.put("publicUrl",url);byte[] hash=MessageDigest.getInstance("SHA-256").digest(EventCodec.JSON.writeValueAsBytes(content));return HexFormat.of().formatHex(hash);}catch(Exception failure){throw new IllegalStateException("CATALOGUE_CHECKSUM_FAILED");}}
    private record Existing(UUID id,UUID related,String kind,int priority,boolean active,long version){} private record KnowledgeRow(UUID id,long revision,String name,String description,JsonNode specifications){}
}
